public class Solution {
    public int KthElement(List<int> a, List<int> b, int k) {

        // Raj Thomas 8th Jun 2026 2:48AM IST 
        int len1 = a.Count, len2 = b.Count;
        int totalLen = len1 + len2;

        if(len1 > len2) return KthElement(b, a, k);

        int leftSidePartition = k;
        int low = Math.Max(0, k - len2), high = Math.Min(len1, k); // this is the tricky part

        while(low <= high) {

            int l1 = int.MinValue, l2 = int.MinValue;
            int r1 = int.MaxValue, r2 = int.MaxValue;

            int mid1 = low + (high - low) / 2;
            int mid2 = leftSidePartition - mid1;

            if(mid1 < len1) r1 = a[mid1];
            if(mid2 < len2) r2 = b[mid2];
            if(mid1 - 1 >= 0) l1 = a[mid1 - 1];
            if(mid2 - 1 >= 0) l2 = b[mid2 - 1];

            if(l1 <= r2 && l2 <= r1 && (mid1 + mid2 == k)) {
                return Math.Max(l1, l2);
            }
            else if(l1 > r2) {
                high = mid1 - 1;
            }
            else {
                low = mid1 + 1;
            }

        }

        return -1;

    }
