class Solution {
  kthElement(arr1, arr2, k) {
    const n1 = arr1.length,
      n2 = arr2.length;

    const left = k; // same as previous but keep k eles in left array

    let low = -1, // low should be -1 because there might be a case where left arr might not pick any ele from first arr
      high = n1 - 1;
    while (low <= high) {
      // mid1, mid2 will be ends of left arr1, arr2 respectively
      let mid1 = Math.floor((low + high) / 2);
      if (mid1 >= left) {
        // edge cases where we might endup taking left arr eles more than required
        mid1 = left - 1;
      }
      const mid2 = left - (mid1 + 1) - 1;

      const l1 = mid1 >= 0 ? arr1[mid1] : -Infinity;
      const r1 = mid1 + 1 < n1 ? arr1[mid1 + 1] : Infinity;
      const l2 = mid2 >= 0 ? arr2[mid2] : -Infinity;
      const r2 = mid2 + 1 < n2 ? arr2[mid2 + 1] : Infinity;

      if (l1 <= r2 && l2 <= r1) {
        return Math.max(l1, l2);
      } else if (l1 > r2) {
        high = mid1 - 1;
      } else {
        low = mid1 + 1;
      }
    }
    return -1;
  }
}
